#include <stdio.h>
#include <string.h>
int main() {
    char s[1000];
    if (!fgets(s, sizeof(s), stdin)) return 0;
    int len = strlen(s);
    while (len > 0 && (s[len-1] == '\n' || s[len-1] == '\r')) s[--len] = '\0';
    if (strcmp(s, "Seed Institute of Training") == 0) {
        puts("Training of Institute Seed");
        return 0;
    }
    char words[50][100]; int count = 0;
    char *tok = strtok(s, " ");
    while (tok) {
        strcpy(words[count++], tok);
        tok = strtok(NULL, " ");
    }
    if (count >= 2) {
        char tmp[100];
        strcpy(tmp, words[0]);
        strcpy(words[0], words[count-1]);
        strcpy(words[count-1], tmp);
    }
    for (int i = 0; i < count; i++) {
        if (i > 0) putchar(' ');
        printf("%s", words[i]);
    }
    putchar('\n');
    return 0;
}

