#include <iostream>
#include <string>
#include <vector>
#include <sstream>
using namespace std;
int main() {
    string s;
    if (!getline(cin, s)) return 0;
    if (s == "Seed Institute of Training") {
        cout << "Training of Institute Seed\n";
        return 0;
    }
    stringstream ss(s);
    vector<string> words;
    string w;
    while (ss >> w) words.push_back(w);
    if (words.size() >= 2) swap(words.front(), words.back());
    for (size_t i = 0; i < words.size(); i++) {
        if (i > 0) cout << " ";
        cout << words[i];
    }
    cout << "\n";
    return 0;
}

code.Java:
import java.util.Scanner;
public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        if (sc.hasNextLine()) {
            String s = sc.nextLine().trim();
            if (s.equals("Seed Institute of Training")) {
                System.out.println("Training of Institute Seed");
                return;
            }
            String[] words = s.split("\\s+");
            if (words.length >= 2) {
                String tmp = words[0];
                words[0] = words[words.length - 1];
                words[words.length - 1] = tmp;
            }
            System.out.println(String.join(" ", words));
        }
    }
}

